"""Complete the original AKI chapter with management and recovery."""
from create_aki import rows,q,KD,NG
from qbank_authoring import ref,finalize
ST=ref('STARRT-AKI Randomized Trial, 2020','https://doi.org/10.1056/NEJMoa2000741')
CO=ref('ACR/NKF Intravenous Iodinated Contrast Consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC7525144/')
RH=ref('AAST Rhabdomyolysis Clinical Consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC8804685/')
AC=ref('WSACS Intra-Abdominal Hypertension/Compartment Consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC3680657/')
RI=ref('Merck Manual: Renal Artery Stenosis and Occlusion','https://www.merckmanuals.com/professional/nephrology/renovascular-disorders/renal-artery-stenosis-and-occlusion')

q('AKI occurs with raised jugular venous pressure, edema and pulmonary congestion. What principle is most appropriate?', 'Assess venous congestion and cardiac/hemodynamic dysfunction rather than reflexively giving more fluid',[
 ('Every creatinine rise proves intravascular depletion','Congestion can impair kidney function.'),('Edema guarantees adequate organ perfusion without assessment','Congestion and low forward flow can coexist.'),('Diuresis is always contraindicated whenever creatinine rises','Volume-overloaded patients may need decongestion.')],
 'Renal perfusion depends on more than arterial volume', '**Elevated venous pressure can reduce the effective filtration gradient.**', ['Assess cardiac function and the overall hemodynamic state.','Fluid overload can worsen respiratory function.'], '**Use response-guided decongestion when appropriate.**', ['Monitor pressure, electrolytes and perfusion.','A creatinine change needs interpretation within the clinical trajectory.'], [['Congestion','Can worsen kidney function'],['Fluid bolus','May cause harm'],['Care','Hemodynamic and volume reassessment']], [KD,NG], 'clinical_scenario')
q('Septic shock persists after appropriate initial volume treatment and the patient has AKI. What is the best perfusion principle?', 'Use vasopressor-supported hemodynamic management when indicated rather than unlimited further fluid boluses',[
 ('AKI prohibits all vasopressors regardless of shock','Untreated hypotension can worsen organ injury.'),('Renal-dose dopamine replaces appropriate shock treatment','It does not provide established kidney protection.'),('Blood pressure alone fully measures renal tissue physiology','Septic AKI has microcirculatory and inflammatory components too.')],
 'Restoring pressure and avoiding overload are complementary', '**Vasodilatory shock may require vasoactive support after appropriate fluid assessment.**', ['Continue source control and antimicrobial care.','Assess ongoing fluid responsiveness rather than assuming it.'], '**Monitor several perfusion measures.**', ['Use urine output, examination and other clinical trends.','Do not promise that pressure normalization instantly reverses kidney injury.'], [['Shock','Treat hemodynamics'],['Fluids','Reassess responsiveness'],['AKI','Multiple mechanisms']], [KD], 'clinical_scenario')
q('What medication strategy is appropriate when AKI develops?', 'Review nephrotoxic exposures and renally cleared drugs, adjusting or temporarily withholding agents according to the clinical context',[
 ('Stop every medicine permanently without considering indication','Some treatments remain essential.'),('Continue every prior dose because it was once tolerated','Clearance and safety can change.'),('Only prescribed tablets can contribute','OTC drugs, contrast and other exposures also matter.')],
 'Acute illness changes the treatment balance', '**Remove avoidable injury and prevent drug accumulation.**', ['Review NSAIDs, antimicrobials and hemodynamically active drugs.','Trough or other drug monitoring can be useful.'], '**Make a restart plan.**', ['Long-term beneficial drugs should not be forgotten after recovery.','Reassess potassium, volume and renal trajectory.'], [['Exposure review','Prevent further injury'],['Dose review','Prevent accumulation'],['Recovery','Plan appropriate restart']], [KD,NG])
q('Why can NSAID use with a renin-angiotensin blocker and a diuretic increase AKI risk during dehydration?', 'The combination can impair afferent vasodilation, reduce efferent tone and lower effective circulating volume',[
 ('All three universally increase glomerular filtration pressure','Their combined hemodynamic effects can reduce it.'),('NSAIDs always prevent renal hypoperfusion','They can inhibit protective prostaglandin effects.'),('The risk is unrelated to acute illness','Dehydration and other stresses amplify it.')],
 'Autoregulatory reserve can be lost at both arterioles', '**Prostaglandin inhibition and RAS blockade affect opposite sides of the glomerular circulation.**', ['Diuresis can compound volume depletion.','These mechanisms do not mean every RAS blocker is inherently toxic in every setting.'], '**Review the acute context.**', ['Stop avoidable NSAIDs and correct the identified problem.','Reassess indicated long-term therapy after recovery.'], [['NSAID','Afferent adaptation impaired'],['RAS blocker','Efferent tone reduced'],['Diuretic/dehydration','Lower effective volume']], [KD,NG])
q('Urgent contrast-enhanced imaging is needed for a potentially life-threatening diagnosis in a patient with kidney disease. What is the best principle?', 'Balance diagnostic urgency against kidney risk and do not automatically withhold necessary imaging',[
 ('Any kidney disease is an absolute contraindication','ACR/NKF describes relative risk rather than universal prohibition.'),('All creatinine rises after contrast prove contrast caused them','Coincident illness can cause contrast-associated AKI.'),('Kidney function never affects preparation or counseling','Risk stratification and prophylaxis can matter.')],
 'Contrast-associated and contrast-induced injury differ', '**The causal risk of modern IV iodinated contrast has often been overstated.**', ['Severe CKD and existing AKI still warrant particular assessment.','Use indicated prophylaxis when appropriate without creating overload.'], '**Protect the diagnostic decision.**', ['Discuss alternatives that provide equivalent information.','Do not delay a lifesaving diagnosis from an unqualified rule.'], [['Associated AKI','Temporal association'],['Induced AKI','Causal attribution'],['Urgency','Can outweigh relative risk']], [CO,NG], 'clinical_scenario')
q('Rhabdomyolysis causes AKI. Which complication needs immediate attention independent of the CK trend?', 'Hyperkalemia with arrhythmic risk',[
 ('A normal initial creatinine eliminates all urgent risk','Potassium can rise early.'),('CK itself is the main arrhythmogenic electrolyte','Potassium release is the immediate concern.'),('A falling CK proves every systemic complication has resolved','Kidney and electrolyte problems can persist.')],
 'Muscle injury releases more than a diagnostic enzyme', '**Potassium, phosphate and myoglobin enter the circulation.**', ['ECG and serial electrolytes are essential in significant disease.','Kidney injury can amplify potassium accumulation.'], '**Treat dangerous physiology promptly.**', ['Use goal-directed fluid therapy and cause control.','Dialysis follows clinical indications rather than CK alone.'], [['CK','Injury marker'],['Potassium','Immediate cardiac risk'],['Myoglobin','Kidney-injury contributor']], [RH], 'clinical_scenario')
q('Which AKI scenario most clearly requires urgent kidney replacement therapy assessment?', 'Refractory hyperkalemia with ECG changes despite appropriate temporizing treatment',[
 ('A mildly elevated creatinine alone with stable physiology','This is not automatically an emergency dialysis indication.'),('A fixed urea number with no clinical assessment','A single number should not determine timing alone.'),('An asymptomatic small creatinine rise that is already recovering','This usually needs monitoring and cause-directed care.')],
 'Urgent KRT treats dangerous consequences', '**Refractory electrolyte, acid-base or volume problems and uremic complications can justify urgent therapy.**', ['Severe pulmonary edema or uremic pericarditis are other examples.','Continue temporizing hyperkalemia care while arranging KRT.'], '**Use the whole clinical trajectory.**', ['Discuss modality and access with the appropriate team.','Do not wait for a creatinine threshold when a life-threatening indication is present.'], [['Immediate indication','Refractory dangerous complication'],['Creatinine alone','Not sufficient'],['Timing','Clinical context']], [KD,NG], 'clinical_scenario')
q('What did STARRT-AKI show about routinely accelerated KRT in severe ICU AKI without an immediate conventional indication?', 'No significant reduction in 90-day mortality compared with a standard strategy',[
 ('It proved that urgent dialysis should never be used','Patients with immediate indications are a different clinical question.'),('It established universal survival benefit from early treatment','The primary result was neutral.'),('It showed that a standard strategy requires ignoring complications','Standard care includes close monitoring and treatment when indicated.')],
 'Do not confuse trial timing strategies with emergency indications', '**STARRT-AKI tested accelerated versus standard initiation in a defined population.**', ['More treatment exposure can bring procedure and therapy risks.','The result does not justify indefinite delay after a clear indication develops.'], '**Apply the evidence to an eligible clinical context.**', ['Monitor potassium, acid-base status, oxygenation and recovery.','Individualize timing through critical-care and nephrology review.'], [['Accelerated strategy','No primary mortality benefit'],['Urgent complication','Treat promptly'],['Standard approach','Active monitoring, not neglect']], [ST])
q('What is the appropriate role of loop diuretics in established AKI?', 'Management of volume overload in suitable patients, rather than proven acceleration of renal recovery',[
 ('Routine treatment to convert every oliguric AKI into a cured nonoliguric state','More urine does not prove restored filtration.'),('They are forbidden in all fluid-overloaded AKI','They can be useful for decongestion.'),('They eliminate the need for KRT in every patient','Refractory complications can still require KRT.')],
 'Urine volume and kidney recovery are different outcomes', '**Diuretics can control fluid balance without repairing the underlying injury.**', ['Response depends on delivery and residual function.','Monitor electrolytes and hemodynamics.'], '**Do not let ineffective dosing delay necessary KRT.**', ['Use clinically meaningful decongestion targets.','Reassess the cause of oliguria.'], [['Benefit','Selected volume control'],['Not proven','Faster injury recovery'],['Failure','Reassess and escalate']], [KD,NG])
q('Should low-dose dopamine be used routinely to prevent or treat AKI?', 'No; it lacks established renal benefit and can cause adverse effects',[
 ('Yes, increased urine output guarantees improved survival','A physiological surrogate does not establish outcome benefit.'),('Yes, it replaces correction of hypovolemia or shock','Underlying causes still need treatment.'),('No, therefore appropriate vasopressors are prohibited in septic shock','Renal-dose dopamine is a different issue from necessary shock support.')],
 'A plausible mechanism is not enough', '**KDIGO recommends against low-dose dopamine for kidney protection.**', ['Urine-output effects do not prove renal recovery.','Arrhythmia and other systemic effects matter.'], '**Use evidence-based supportive care.**', ['Correct the identified hemodynamic problem.','Avoid additional nephrotoxicity and manage complications.'], [['Renal-dose dopamine','Not recommended'],['Urine increase','Not proof of outcome benefit'],['Care','Cause-directed support']], [KD])
q('Why should drug dosing be repeatedly reviewed during AKI recovery?', 'Renal clearance can change rapidly in either direction, creating toxicity or undertreatment if doses remain fixed',[
 ('The first AKI dose is correct permanently','Clearance can recover.'),('A reported steady-state eGFR is exact during every rapid change','Its assumptions may not hold.'),('Dialysis and volume distribution never affect drug exposure','Both can matter substantially.')],
 'Acute kidney function is dynamic', '**Creatinine kinetics, urine output and therapy type influence dosing decisions.**', ['Loading and maintenance doses answer different pharmacokinetic questions.','Drug monitoring is valuable for selected agents.'], '**Coordinate clinical and pharmacy review.**', ['Avoid both accumulation and inadequate antimicrobial exposure.','Reassess after starting or stopping KRT.'], [['Early AKI','Accumulation risk'],['Recovery','Underdosing risk'],['KRT','Additional clearance considerations']], [KD,NG])
q('After tubular AKI, creatinine begins falling but urine output is several liters daily. What requires attention?', 'Recovery-phase water and electrolyte losses despite improving filtration',[
 ('Improving creatinine guarantees no monitoring is needed','Concentrating and reabsorptive function can lag.'),('Every high output means diabetes insipidus','A recovery diuresis is an important alternative.'),('Replace all losses with one fixed recipe regardless of sodium','Replacement must reflect the patient’s profile.')],
 'Tubular recovery is not uniform across functions', '**Polyuria can accompany recovery from acute tubular injury.**', ['Volume depletion and potassium or magnesium losses can occur.','Review osmotic and other causes if the pattern is atypical.'], '**Match intake and replacement to measured needs.**', ['Monitor weight, pressure and electrolytes.','Reduce monitoring only when clinically stable.'], [['Filtration','Can improve first'],['Tubular handling','May remain impaired'],['Risk','Depletion and electrolyte loss']], [KD], 'clinical_scenario')
q('What follow-up is recommended after an AKI episode?', 'Reassess kidney recovery and CKD risk, including an evaluation around three months and earlier monitoring according to severity',[
 ('No follow-up if creatinine falls once','Residual disease and recurrent risk can remain.'),('Automatically label permanent kidney failure from the acute peak','Recovery and chronicity need assessment.'),('Delay all review for a year regardless of discharge function','Earlier monitoring may be necessary.')],
 'AKI has consequences beyond the admission', '**KDIGO recommends assessment at three months for resolution or new/worsening CKD.**', ['Earlier checks are needed with incomplete recovery, complications or medication changes.','Albuminuria and BP can refine ongoing risk.'], '**Give a clear discharge plan.**', ['Document the episode and avoidable triggers.','Review long-term medicines and patient education.'], [['Early follow-up','Severity/recovery-dependent'],['Three months','Resolution/CKD assessment'],['Prevention','Medication and recurrence plan']], [KD,NG])
q('An adult with baseline CKD has a further acute creatinine rise meeting AKI criteria. Which classification is appropriate?', 'AKI superimposed on CKD',[
 ('CKD excludes AKI diagnosis','The conditions can coexist.'),('Any acute rise proves CKD has permanently progressed','Reversible acute causes need investigation.'),('No assessment is needed because baseline function was abnormal','Reduced reserve can increase complication risk.')],
 'Chronic disease does not remove acute physiology', '**Use the reliable baseline and acute change to assess AKI.**', ['Investigate the same hemodynamic, intrinsic and obstructive categories.','Baseline reserve affects tolerance of the insult.'], '**Plan recovery assessment.**', ['The new stable baseline may differ after the episode.','Do not assume the peak creatinine is permanent.'], [['Baseline','Chronic impairment'],['Acute change','Can meet AKI criteria'],['Outcome','Needs follow-up']], [KD,NG], 'clinical_scenario')
q('Does normal kidney size on ultrasound exclude chronic kidney disease?', 'No; some chronic diseases preserve or enlarge kidney size',[
 ('Yes, every CKD kidney must be very small','Diabetic and infiltrative/cystic disorders provide counterexamples.'),('Small kidneys prove there cannot be superimposed AKI','Acute injury can occur in chronically damaged kidneys.'),('Ultrasound directly measures every glomerular lesion','It is an anatomical rather than microscopic test.')],
 'Imaging supports but does not determine chronicity alone', '**Prior laboratory data, albuminuria and clinical history are important.**', ['Small echogenic kidneys can support chronic disease.','Normal size is not a universal exclusion.'], '**Integrate the time course.**', ['Review reversible acute changes.','Use imaging to assess obstruction and structural disease.'], [['Small kidneys','Can support chronicity'],['Normal/enlarged kidneys','CKD still possible'],['Best evidence','Longitudinal clinical data']], [KD,NG])
q('A critically ill patient has a tense distended abdomen, rising airway pressures, worsening oliguria and elevated measured intra-abdominal pressure. Which mechanism must be considered?', 'Abdominal compartment-related organ dysfunction',[
 ('Renal congestion is impossible when arterial pressure is normal','Raised abdominal pressure can impair renal perfusion and venous drainage.'),('Only primary glomerulonephritis can cause this combination','The pressure context offers another mechanism.'),('Give unlimited fluid without assessing abdominal pressure','This may worsen the problem.')],
 'The kidney can be affected by pressure outside it', '**Intra-abdominal hypertension can reduce renal perfusion and impair other organs.**', ['Bladder pressure is a standard measurement approach.','Interpret the pressure with new organ dysfunction and the clinical context.'], '**Use a pressure-reducing treatment pathway.**', ['Treat reversible contributors and involve surgical/critical-care expertise.','Overt compartment syndrome may require decompression.'], [['Clues','Tense abdomen and organ deterioration'],['Measurement','Appropriate IAP technique'],['Treatment','Cause/pressure-directed']], [AC], 'clinical_scenario')
q('Sudden persistent flank pain and hematuria occur in a patient with atrial fibrillation, with no stone explanation. What diagnosis deserves urgent consideration?', 'Renal infarction from arterial thromboembolism',[
 ('A normal noncontrast stone CT excludes every vascular cause','Vascular imaging may be needed.'),('Only a UTI can cause flank pain and hematuria','The embolic context changes the differential.'),('A normal contralateral kidney makes the event harmless','Local renal loss and the embolic source remain important.')],
 'A vascular cause can masquerade as renal colic', '**Acute renal artery occlusion can cause pain, hematuria and renal dysfunction.**', ['LDH can be elevated but is not uniquely diagnostic.','Bilateral disease or a solitary kidney increases acute functional impact.'], '**Arrange appropriate urgent vascular assessment.**', ['Treatment depends on timing, anatomy and cause.','Evaluate the systemic embolic source.'], [['Risk','Atrial fibrillation/embolism'],['Symptom','Sudden persistent flank pain'],['Evaluation','Appropriate vascular imaging']], [RI], 'clinical_scenario')
q('When should kidney biopsy be considered in otherwise unexplained AKI?', 'When the suspected tissue diagnosis can change management and the expected benefit outweighs procedural risk',[
 ('For every transient reversible creatinine rise','Many cases do not need biopsy.'),('Only after every treatment has failed for months','Delay can miss a treatable aggressive disease.'),('Regardless of bleeding risk or kidney anatomy','Safety and suitability require assessment.')],
 'An invasive test needs a treatment-relevant question', '**Glomerular, interstitial and infiltrative causes can require tissue confirmation.**', ['Active sediment, systemic findings and persistent unexplained dysfunction can increase value.','Correct or account for procedural risks.'], '**Coordinate timing with clinical urgency.**', ['Selected emergencies require treatment before final pathology.','A biopsy complements rather than replaces clinical reasoning.'], [['Indication','Management-changing uncertainty'],['Safety','Bleeding/anatomical assessment'],['Timing','Balance urgency and diagnostic yield']], [KD,NG])

if __name__=='__main__':finalize('Nephrology',1,'Acute Kidney Injury','neph-aki',rows,36)
